247: function tinkers_list_for_craft(self, t)
248: 	local l = {}
249: 	l[#l+1] = _t"This talent is required for the following tinkers (you still need to learn/find the schematics):"
250: 	for tid, tinker in pairs(game.party.__tinkers_ings) do if tinker.random_schematic and not tinker.unique and tinker.talents and tinker.talents[t.id] then
251: 		local known = ""
252: 		if game.party:knowTinker(tinker.id) then known = _t" #LIGHT_BLUE#(known)#LAST#" end
253: 		l[#l+1] = "#{italic}#* "..tinker.name..known.."#{normal}#"
254: 	end end
255: 	l[#l+1] = _t"#{italic}#* ...perhaps more to discover...#{normal}#"
256: 	return table.concat(l, "\n")
